import{_ as t,o as s,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const n="/eep/ini-edit-translate-2026/editor-v2-1-37-fr.png",a="/eep/ini-edit-translate-2026/info-trans-v2-1-37-fr.png",o="/eep/ini-edit-translate-2026/dictionary-v2-1-37-fr.png",g=JSON.parse('{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT.","frontmatter":{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT."},"headers":[],"relativePath":"fr/eep/ini-edit-translate-2026/index.md","filePath":"fr/eep/ini-edit-translate-2026/index.md","lastUpdated":1793006827000}'),d={name:"fr/eep/ini-edit-translate-2026/index.md"};function l(c,e,u,p,m,f){return s(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><h2 id="version-2-1-55-dictionnaire-csv-externe-prioritaire" tabindex="-1">Version 2.1.55 : dictionnaire CSV externe prioritaire <a class="header-anchor" href="#version-2-1-55-dictionnaire-csv-externe-prioritaire" aria-label="Permalink to &quot;Version 2.1.55 : dictionnaire CSV externe prioritaire&quot;">​</a></h2><p>Le dictionnaire initial contient les 30 termes de la liste utilisateur en allemand, anglais, français et polonais, avec accents et caractères spéciaux corrigés. Le premier démarrage crée un CSV externe UTF-8 séparé par des points-virgules : <code>%LOCALAPPDATA%\\UGSo\\IET2026\\translation-dictionary.csv</code>.</p><div class="language-csv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Deutsch;ENG;FRA;POL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Arbeiter;Worker;Ouvrier;Robotnik</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Ajouter des lignes ou corriger les traductions. Chaque nouvelle traduction relit le fichier. Les correspondances externes sont prioritaires sur la liste intégrée, le vocabulaire existant des modèles et le fournisseur en ligne choisi. Les expressions complètes sont reconnues dans les quatre langues sources. Un texte entièrement couvert ne nécessite aucune requête en ligne. Les noms propres inconnus dans les noms de modèles restent inchangés. Une cellule cible vide utilise le repli. Les fichiers absents, illisibles ou mal formés ne sont pas modifiés ; la liste intégrée reste disponible. Les résultats en ligne ne sont jamais ajoutés automatiquement au CSV. La lecture est limitée à 1 Mio et 2 000 lignes de données, avec 200 caractères sans caractères de contrôle par cellule.</p><p>Les mises à jour n’écrasent jamais un CSV utilisateur existant. Paramètres, identifiants d’accès, entrées personnelles, base Info_trans et tableaux de référence sont conservés. DR, DB, codes de constructeurs, types techniques, identifiants avec tirets bas, versions et <code>[e]</code> restent protégés, même contre des entrées CSV contradictoires. La liste initiale est intégrée au programme et créée à l’extérieur uniquement au démarrage, afin que le ZIP reste compatible avec les anciens programmes de mise à jour.</p><p>116 vérifications locales et 43 vérifications de mise à jour réussies, y compris le ZIP complet et la conservation des entrées personnelles. Aucun appel réel aux API. L’éditeur INI utilise le concepteur Framework classique ; une nouvelle vérification directement dans Visual Studio reste attendue.</p><h3 id="verification-utilisateur-de-la-version-2-1-55" tabindex="-1">Vérification utilisateur de la version 2.1.55 <a class="header-anchor" href="#verification-utilisateur-de-la-version-2-1-55" aria-label="Permalink to &quot;Vérification utilisateur de la version 2.1.55&quot;">​</a></h3><p>Le 24 octobre 2026, l’utilisateur a confirmé que la mise à jour vers la version 2.1.55 s’était déroulée correctement. Le processus de mise à jour est ainsi confirmé en utilisation réelle, en complément des vérifications automatisées.</p><h2 id="version-2-1-54-abreviations-ferroviaires-dans-info-trans" tabindex="-1">Version 2.1.54 : abréviations ferroviaires dans Info_trans <a class="header-anchor" href="#version-2-1-54-abreviations-ferroviaires-dans-info-trans" aria-label="Permalink to &quot;Version 2.1.54 : abréviations ferroviaires dans Info_trans&quot;">​</a></h2><p>Info_trans ajoute l’onglet <strong>Abréviations ferroviaires</strong> avec 14 entrées : Bf, Hbf, Hp, Gbf, Rbf, Abzw, BÜ, Stw, EG, OL, Gl., Bstg., DWW et Kr. Le tableau présente l’allemand, l’anglais, le français et le polonais, avec les abréviations étrangères attestées. La ligne Kr., auparavant vide, est complétée pour une traversée de voies. Cliquer sur une cellule copie son contenu, comme dans les autres tableaux de référence. Le tableau est en lecture seule, les colonnes peuvent être triées et les textes longs passent à la ligne. L’onglet allemand s’appelle <strong>Bahnabkürzung</strong>, l’anglais <strong>Railway abbreviations</strong>. Le tableau est intégré dans Info_trans. Un fichier externe existant <code>help/railway-abbreviations.csv</code> reste utilisable. Ce tableau de référence ne modifie pas les règles de traduction automatique. Sauvegarde effectuée avant modification ; dictionnaire, base de données, paramètres, identifiants d’accès et liste externe des constructeurs sont conservés. Le ZIP de mise à jour utilise uniquement les chemins acceptés par le programme de mise à jour 2.1.53. Téléchargement et validation sont distincts ; 100 % n’est affiché qu’après validation. Les détails d’erreur sont visibles et une nouvelle tentative est possible. Les deux projets conservent .NET Framework 4.8 et utilisent son concepteur Visual Studio adapté à chaque projet. Info_trans référence explicitement System.Configuration. Recharger la solution après modification. Compilation de conception et chargement WinForms DesignSurface vérifiés ; Visual Studio lui-même n’a pas été piloté à distance.</p><p>114 vérifications locales réussies : contenu du tableau et affichage DE/EN/FR aux échelles 100 et 150 %, sans appel réel aux API.</p><h3 id="verification-utilisateur-de-la-version-2-1-54" tabindex="-1">Vérification utilisateur de la version 2.1.54 <a class="header-anchor" href="#verification-utilisateur-de-la-version-2-1-54" aria-label="Permalink to &quot;Vérification utilisateur de la version 2.1.54&quot;">​</a></h3><p>Le 24 octobre 2026, l’utilisateur a confirmé la réussite de la mise à jour vers 2.1.54 et la présence de l’onglet <strong>Abréviations ferroviaires</strong>. L’ouverture du concepteur Visual Studio avait également été confirmée dans un premier temps. Un signalement ultérieur concernant l’éditeur INI indique que le concepteur ne peut pas être affiché, car aucune des classes du fichier ne peut être prise en charge. La vérification du concepteur est donc de nouveau ouverte ; la mise à jour et l’affichage de l’onglet restent confirmés.</p><p>La classification des fichiers de logique <code>Form1.Update.cs</code> et <code>Form1.Translation.cs</code> dans le projet a ensuite été corrigée en « Code ». Pour modifier la disposition, ouvrir uniquement <code>Form1.cs</code> avec « Afficher le concepteur », et non les fichiers de logique imbriqués. Recharger la solution après actualisation. La compilation et les vérifications DesignSurface des deux formulaires principaux ont réussi ; la nouvelle vérification directement dans Visual Studio reste à effectuer.</p><p>Un nouveau signalement précise que <code>assemblyOutputPath</code> ne peut pas être récupéré depuis <code>VsHierarchy</code>. MSBuild résout pourtant le chemin de sortie. Pour contourner ce problème, l’éditeur INI AnyCPU utilise de nouveau le concepteur Framework classique (<code>UseWinFormsOutOfProcDesigner=False</code>) ; Info_trans conserve son mode actuel. Après actualisation, fermer puis rouvrir la solution, la régénérer et ouvrir <code>Form1.cs</code> dans le concepteur. La confirmation de ce contournement dans Visual Studio reste attendue.</p><h2 id="version-2-1-53-abreviations-ferroviaires-et-codes-de-constructeurs" tabindex="-1">Version 2.1.53 : abréviations ferroviaires et codes de constructeurs <a class="header-anchor" href="#version-2-1-53-abreviations-ferroviaires-et-codes-de-constructeurs" aria-label="Permalink to &quot;Version 2.1.53 : abréviations ferroviaires et codes de constructeurs&quot;">​</a></h2><p>20 abréviations ferroviaires utilisent désormais une correspondance locale fixe dans les noms de modèles et les textes traduits par le fournisseur choisi. EW signifie aiguillage simple, sans exiger un angle après le code. Par exemple, <code>GK3 DKW DR DB (V8)[e]EEP16.2</code> devient <code>GK3 TJD DR DB (V8)[e]EEP16.2</code> en français.</p><p>La liste initiale fournie contient 272 codes de constructeurs uniques de trois caractères. Le premier démarrage crée un fichier UTF-8 externe : <code>%LOCALAPPDATA%\\UGSo\\IET2026\\constructor-codes.txt</code>. Ajouter les nouveaux codes de deux lettres et un chiffre, un par ligne, puis redémarrer. Les mises à jour n’écrasent jamais ce fichier personnel. Les ajouts sont fusionnés avec la liste de base. Lignes vides, commentaires et entrées invalides sont ignorés. Un fichier illisible est conservé et la liste de base sert de solution de repli. Les codes sont conservés partout, avec ou sans parenthèses. La reconnaissance générale des autres codes reste active. DR, DB, types, indications de version comme <code>(V8)</code> ou <code>(v8.2)</code>, versions EEP et <code>[e]</code> restent inchangés.</p><table tabindex="0"><thead><tr><th>DE</th><th>EN</th><th>FR</th><th>PL</th></tr></thead><tbody><tr><td>DKW</td><td>DSS</td><td>TJD</td><td>Rkpd</td></tr><tr><td>EKW</td><td>SS</td><td>TJS</td><td>Rkp</td></tr><tr><td>EW</td><td>single turnout</td><td>BS</td><td>Rz</td></tr><tr><td>ABW</td><td>contrary-flexure turnout</td><td>ABW*</td><td>Rłd</td></tr><tr><td>IBW</td><td>similar-flexure turnout</td><td>IBW*</td><td>Rłj</td></tr><tr><td>BW</td><td>locomotive depot</td><td>dépôt de locomotives</td><td>lokomotywownia</td></tr><tr><td>Bf</td><td>station</td><td>gare</td><td>stacja</td></tr><tr><td>Hbf</td><td>main station</td><td>gare principale</td><td>dworzec główny</td></tr><tr><td>Hp</td><td>halt</td><td>halte ferroviaire</td><td>przystanek osobowy</td></tr><tr><td>Gbf</td><td>freight station</td><td>gare de marchandises</td><td>stacja towarowa</td></tr><tr><td>Rbf</td><td>marshalling yard</td><td>gare de triage</td><td>stacja rozrządowa</td></tr><tr><td>Abzw</td><td>junction</td><td>bifurcation</td><td>posterunek odgałęźny</td></tr><tr><td>BÜ</td><td>level crossing</td><td>passage à niveau</td><td>przejazd kolejowo-drogowy</td></tr><tr><td>Stw</td><td>signal box</td><td>poste d’aiguillage</td><td>nastawnia</td></tr><tr><td>EG</td><td>station building</td><td>bâtiment voyageurs</td><td>budynek dworca</td></tr><tr><td>OL</td><td>overhead line equipment</td><td>caténaire</td><td>sieć trakcyjna</td></tr><tr><td>Gl.</td><td>track</td><td>voie</td><td>tor</td></tr><tr><td>Bstg.</td><td>platform</td><td>quai</td><td>peron</td></tr><tr><td>DWW</td><td>three-way turnout</td><td>branchement à trois voies</td><td>rozjazd potrójny</td></tr><tr><td>Kr.</td><td>diamond crossing</td><td>traversée de voies</td><td>skrzyżowanie torów</td></tr></tbody></table><p>*En français, ABW/IBW sont conservés en attendant une validation terminologique. Les autres entrées utilisent des abréviations attestées ou des traductions en toutes lettres, sans prétendre à une norme universelle. Autres abréviations reconnues en entrée : DS/DSS/SS, TJD/TJS/BS, Rkpd/Rkp/Rz/Rłd/Rłj, PO, Jn, PODG, LC, PN, BV et OLE. Le polonais ambigu ST/St n’est pas converti. Hp désigne ici une halte ferroviaire et Kr. une traversée de voies. Les types techniques <code>Hp0</code>, <code>DKW190</code> et identifiants comme <code>DKW_190</code> ne sont pas découpés.</p><p>Les termes vérifiés sont remplacés temporairement par des marqueurs protégés pour la traduction en ligne, puis rétablis dans la langue cible après validation, y compris lorsque l’anglais sert de langue intermédiaire. Une erreur ou un marqueur modifié empêche toute application partielle. Fichiers originaux, paramètres et identifiants d’accès sont conservés. Sauvegarde effectuée avant modification. MyMemory reste le choix par défaut des nouvelles configurations.</p><p>111 vérifications locales réussies : tous les 272 codes, DE/EN/FR/PL, import/enregistrement/relecture, versions et erreurs, sans appel réel aux API. Le ZIP complet inclut <code>docs/railway-glossary.md</code> et <code>docs/constructor-codes.txt</code>.</p><h2 id="version-2-1-52-mots-descriptifs-dans-les-noms-de-modeles" tabindex="-1">Version 2.1.52 : mots descriptifs dans les noms de modèles <a class="header-anchor" href="#version-2-1-52-mots-descriptifs-dans-les-noms-de-modeles" aria-label="Permalink to &quot;Version 2.1.52 : mots descriptifs dans les noms de modèles&quot;">​</a></h2><p>Les mots descriptifs sont désormais traduits dans les noms de modèles, même si leur description est vide. « Haus Helios Typ4 UD1 » devient <strong>House / Maison / Dom Helios Typ4 UD1</strong>.</p><p>La traduction des noms utilise une liste locale limitée de mots vérifiés pour protéger les noms propres. Les mots inconnus et éléments de noms sont conservés sans être envoyés à un service en ligne pour traduire le nom. Ce n’est pas une reconnaissance générale automatique des noms propres : les autres mots descriptifs doivent être ajoutés après vérification. Les noms existants sans mot descriptif reconnu ne sont pas écrasés. Types, codes de constructeurs, versions EEP, <code>[e]</code>, séparateurs et écriture des éléments protégés sont conservés. Les abréviations ferroviaires encore en cours de collecte ne sont pas ajoutées dans cette modification.</p><p>Les descriptions utilisent toujours le fournisseur choisi. Noms et descriptions ne sont appliqués ensemble qu’après réussite ; une erreur conserve les contenus existants. Le bouton indépendant du fournisseur s’appelle <strong>Traduire les textes</strong>.</p><p><strong>MyMemory/translated.net est le choix par défaut des nouvelles configurations.</strong> Les choix, clés API, comptes et modèles déjà enregistrés sont conservés. Pour changer volontairement : <strong>À propos → Paramètres → Paramètres de traduction → MyMemory → Enregistrer</strong>.</p><p>105 vérifications locales réussies : DE/EN/FR/PL, descriptions vides, protection des noms et codes, erreurs, enregistrement et relecture. Sauvegarde effectuée ; fichiers originaux et identifiants conservés.</p><h2 id="version-2-1-51-message-lors-de-la-selection-d-un-dossier" tabindex="-1">Version 2.1.51 : message lors de la sélection d’un dossier <a class="header-anchor" href="#version-2-1-51-message-lors-de-la-selection-d-un-dossier" aria-label="Permalink to &quot;Version 2.1.51 : message lors de la sélection d’un dossier&quot;">​</a></h2><p>Sélectionner un dossier dans l’arborescence affiche <strong>« Veuillez sélectionner un fichier INI. »</strong> Les textes, tableaux, aperçu et fichier sélectionné sont conservés. Un dossier n’est plus lu comme un fichier et aucune traduction n’est lancée.</p><p>Cela concerne le dossier racine et les sous-dossiers de tout nom, y compris ceux portant une extension <code>.ini</code>. Les fichiers disparus et autres types de fichiers affichent le même message. Seul un fichier INI existant est ouvert ; <code>.INI</code> en majuscules est également reconnu. Le nœud sélectionné remplace la position du pointeur, y compris pour la navigation au clavier. Message disponible en allemand, anglais et français.</p><p>101 vérifications locales réussies, dont conservation des données lors de la sélection d’un dossier dans les trois langues et ouverture d’un INI sans dépendre du pointeur. Sauvegarde effectuée ; données personnelles et identifiants conservés.</p><h2 id="version-2-1-50-proteger-les-controles-eep-identifiants-et-versions" tabindex="-1">Version 2.1.50 : protéger les contrôles EEP, identifiants et versions <a class="header-anchor" href="#version-2-1-50-proteger-les-controles-eep-identifiants-et-versions" aria-label="Permalink to &quot;Version 2.1.50 : protéger les contrôles EEP, identifiants et versions&quot;">​</a></h2><p><code>[e]</code> reste un code de saut de ligne EEP : il n’est ni traduit ni remplacé par un vrai saut de ligne. L’écriture exacte, le nombre et l’ordre des marqueurs protégés sont vérifiés.</p><p>Les identifiants de constructeurs sont reconnus par des motifs lettres/chiffres, sans liste de noms fixe : <code>(GK3)</code>, <code>(AG3)</code>, <code>(DL1)</code>, mais aussi les anciens codes sans parenthèses au début, au milieu ou à la fin. Aucun code n’est ajouté s’il est absent. Les ajouts ordinaires tels que <code>(Winter)</code> restent traduisibles. Sans liste supplémentaire, les codes particuliers composés uniquement de lettres ne peuvent pas être distingués de façon fiable des mots ordinaires.</p><p>Les versions comme <code>EEP16.2</code>, <code>eep16.2</code> et <code>EEP 16.2</code> gardent leur casse et ponctuation. MyMemory ne reçoit pas les segments protégés ; les codes ou contrôles modifiés ou inventés par OpenAI/ChatGPT sont rejetés. La protection par restauration reste active.</p><p>Une entrée de configuration ajoutée en 2.1.49 pouvait empêcher le démarrage. Elle est corrigée et la configuration distribuée est désormais vérifiée. <strong>Si 2.1.49 ne démarre plus :</strong> sauvegarder <code>INI Edit Translate 2026.exe.config</code>, télécharger le fichier de configuration supplémentaire de la version 2.1.50, le renommer <code>INI Edit Translate 2026.exe.config</code> et remplacer celui situé à côté de l’EXE. Démarrer puis installer normalement la mise à jour 2.1.50. Ne pas remplacer les fichiers INI, bases de données ou paramètres personnels.</p><p>99 vérifications locales réussies. Un test d’installation avec code initial, version, code entre parenthèses et deux contrôles <code>[e]</code> a réellement été traduit via MyMemory, enregistré et relu. Fichiers originaux et identifiants conservés.</p><h2 id="version-2-1-49-conserver-le-dernier-dossier" tabindex="-1">Version 2.1.49 : conserver le dernier dossier <a class="header-anchor" href="#version-2-1-49-conserver-le-dernier-dossier" aria-label="Permalink to &quot;Version 2.1.49 : conserver le dernier dossier&quot;">​</a></h2><p>Activer <strong>Conserver le dernier dossier</strong> dans <strong>À propos → Paramètres</strong>, puis <strong>Enregistrer</strong>. Le dernier dossier choisi est conservé après redémarrage et mise à jour. L’arborescence et les sélecteurs de fichiers INI / Installation.eep repartent de ce dossier. Aucun fichier n’est ouvert ni traduit automatiquement.</p><p>L’option est désactivée par défaut. Si un dossier ou lecteur réseau est indisponible, un message apparaît et le chemin est conservé pour le prochain démarrage. Les données et identifiants existants sont conservés. 94 vérifications locales réussies, dont enregistrement/relecture, désactivation, dossier indisponible et affichage DE/EN/FR aux échelles 100/150 %.</p><p><strong>Version 2.1.55.0 · Windows 11 · .NET Framework 4.8</strong></p><p>Modifier les descriptions de modèles EEP et leurs fichiers d’installation. Développé par Uwe Grimm / UGSo Software et publié sous licence MIT.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Code source et README sur GitHub</a></p><p><img src="`+n+'" alt="Interface de la version 2.1.37 avec barre de menus Lime, sans données personnelles"></p><h2 id="version-2-1-48-retablir-la-traduction-des-noms-de-sous-ensembles" tabindex="-1">Version 2.1.48 : rétablir la traduction des noms de sous-ensembles <a class="header-anchor" href="#version-2-1-48-retablir-la-traduction-des-noms-de-sous-ensembles" aria-label="Permalink to &quot;Version 2.1.48 : rétablir la traduction des noms de sous-ensembles&quot;">​</a></h2><p>Les noms et descriptions des cinq sous-ensembles <code>Install_00</code> à <code>Install_04</code> sont de nouveau traduits. Seuls les noms de modèles dans la section des modèles restent protégés. Les textes sources sont conservés ; l’allemand et le français utilisent toujours l’anglais comme langue intermédiaire.</p><p>Les cinq boutons et l’importation automatique utilisent la même correspondance vérifiée des champs. Le bouton du deuxième sous-ensemble traite désormais ses propres champs. Les résultats ne sont appliqués qu’après traduction complète ; une erreur ou une annulation conserve les noms et descriptions du sous-ensemble.</p><p>91 vérifications locales réussies. Un sous-ensemble de test nommé « Detailmodell Großdiesellokomotive V140 001 DRG » a réellement été traduit via MyMemory, enregistré et relu ; les noms de modèles et un champ INI supplémentaire ont été conservés. Le fichier de l’ordinateur de jeu distant n’a pas été modifié.</p><h2 id="telechargement" tabindex="-1">Téléchargement <a class="header-anchor" href="#telechargement" aria-label="Permalink to &quot;Téléchargement&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.55/INI-Edit-Translate-2026-v2.1.55-windows.zip" target="_blank" rel="noreferrer">Télécharger le ZIP Windows v2.1.55</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.55" target="_blank" rel="noreferrer">Version GitHub et SHA-256</a></p><p>Extraire tout le ZIP et lancer <code>INI Edit Translate 2026.exe</code>. Windows 11 et .NET Framework 4.8 sont requis. Conserver les DLL et dossiers de langues ensemble. Visual Studio sert uniquement à compiler les sources. Aucun installateur nécessaire.</p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domaine</th><th>Possibilités</th></tr></thead><tbody><tr><td>Textes de modèles</td><td>Modifier les noms et descriptions en EN/DE/FR/PL</td></tr><tr><td>Métadonnées</td><td>Modifier les références PDF, génération, années d’utilisation, pays et icône</td></tr><tr><td>Axes de mouvement et fonctions des signaux</td><td>Afficher, modifier et traduire les entrées par langue</td></tr><tr><td>Installation.eep</td><td>Modifier les noms et descriptions des sections d’installation prises en charge</td></tr><tr><td>Aperçu</td><td>Comparer le fichier original à l’aperçu du résultat</td></tr><tr><td>Export des tableaux</td><td>Export complet en UTF-8 avec BOM et séparateurs de tabulation</td></tr><tr><td>Sauvegardes</td><td>Copier les fichiers INI existants avant remplacement, en conservant leur nom d’origine</td></tr></tbody></table><h2 id="fournisseurs-de-traduction" tabindex="-1">Fournisseurs de traduction <a class="header-anchor" href="#fournisseurs-de-traduction" aria-label="Permalink to &quot;Fournisseurs de traduction&quot;">​</a></h2><p>Dans <strong>Options → Paramètres de traduction</strong>, choisir API OpenAI, abonnement ChatGPT ou <strong>MyMemory</strong>. MyMemory nécessite Internet, mais aucune clé ni aucun compte. Une adresse e-mail facultative est envoyée avec chaque requête : selon le fournisseur, 5 000 caractères par jour sans identification, jusqu’à 50 000 avec une adresse valide. Chaque langue cible compte séparément. Les textes longs sont découpés en segments de 500 octets UTF-8 maximum. Un cache temporaire évite les répétitions pendant une opération.</p><p>L’allemand est la langue par défaut. La langue choisie pour l’interface définit la langue source initiale ; les axes/fonctions des signaux gardent leur sélecteur de source. L’allemand et le français sont d’abord traduits en anglais ; les autres langues cibles utilisent ce texte intermédiaire anglais. Cela vaut pour tous les fournisseurs. Le texte source choisi et les noms de modèles sont conservés.</p><p>MyMemory peut conserver durablement les textes transmis. L’application utilise uniquement la requête de traduction et ne publie pas d’entrées supplémentaires dans un dictionnaire. Aucun changement automatique de fournisseur. Les clés API, connexions ChatGPT, modèles et dictionnaires existants sont conservés. L’enregistrement INI préserve les caractères polonais grâce à Unicode ; si nécessaire, le fichier de sortie sauvegardé est enregistré en UTF-16 avec BOM. Le traitement réel de cet encodage dans EEP n’a pas été testé ici.</p><p>90 vérifications locales ont réussi. Le fichier INI fourni a été ouvert, traduit par de véritables appels MyMemory et enregistré dans une copie ; l’original reste inchangé. Relire les traductions automatiques des termes techniques avant utilisation.</p><p><a href="https://mymemory.translated.net/doc/spec.php" target="_blank" rel="noreferrer">API MyMemory</a> · <a href="https://mymemory.translated.net/doc/usagelimits.php" target="_blank" rel="noreferrer">Quotas</a> · <a href="https://mymemory.translated.net/terms-and-conditions" target="_blank" rel="noreferrer">Utilisation des données</a></p><h2 id="installation-et-utilisation" tabindex="-1">Installation et utilisation <a class="header-anchor" href="#installation-et-utilisation" aria-label="Permalink to &quot;Installation et utilisation&quot;">​</a></h2><ol><li>Télécharger le ZIP Windows ci-dessus et extraire tous les fichiers.</li><li>Lancer <code>INI Edit Translate 2026.exe</code> depuis le dossier extrait en conservant ses DLL et dossiers de langues.</li><li>Ouvrir <strong>À propos → Paramètres → Paramètres de traduction</strong>. Choisir MyMemory, API OpenAI ou abonnement ChatGPT. MyMemory ne nécessite pas de connexion ; l’e-mail est facultatif.</li><li>Ouvrir d’abord une copie sauvegardée en mode <strong>Lecture seule</strong>.</li><li>Utiliser <strong>Lire et traduire</strong> ou un bouton de traduction. Choisir la langue source des axes et fonctions des signaux.</li><li>Vérifier l’aperçu et les textes, puis enregistrer explicitement.</li></ol><p>La fenêtre d’information choisit l’aide révisée <code>Info.de.rtf</code>, <code>Info.en.rtf</code> ou <code>Info.fr.rtf</code> selon la langue de l’interface. Le fichier historique <code>Info.rtf</code> est conservé sans modification. L’aide actuelle décrit OpenAI et le programme de référence restauré.</p><h2 id="mises-a-jour-github" tabindex="-1">Mises à jour GitHub <a class="header-anchor" href="#mises-a-jour-github" aria-label="Permalink to &quot;Mises à jour GitHub&quot;">​</a></h2><p>Choisir <strong>À propos → Rechercher des mises à jour</strong> pour consulter la dernière version publique sur GitHub. Aucune vérification automatique au démarrage. Seule une version stable plus récente est proposée, avec son numéro et ses notes de publication.</p><p><strong>Télécharger et installer</strong> récupère le ZIP Windows et sa somme SHA-256. Le téléchargement et la vérification peuvent être annulés avant la fermeture du programme. Enregistrer les fichiers ouverts et fermer Info_trans avant l’installation, puis confirmer. Un programme auxiliaire attend la fermeture de l’éditeur, sauvegarde les fichiers existants et installe le paquet.</p><p>Les paramètres et la clé OpenAI chiffrée sont conservés. Les fichiers FDB, CSV, DAT et de configuration existants de l’aide, ainsi que l’Info.rtf d’origine, sont sauvegardés sans être remplacés. Les fichiers de modèles restent intacts. En cas d’échec, le programme tente de restaurer les fichiers déjà remplacés et consigne le résultat. Sauvegardes et rapports : <code>%LOCALAPPDATA%/UGSo/IET2026/updates/&lt;identifiant&gt;/</code>.</p><p>Aucun identifiant de serveur nécessaire. Les sommes de contrôle vérifient l’intégrité ; aucune signature numérique de paquet supplémentaire n’est implémentée. 36 tests isolés couvrent le téléchargement, l’annulation, les chemins, la conservation des données, les fichiers verrouillés et la restauration après une écriture partielle.</p><h3 id="correction-du-programme-de-mise-a-jour-2-1-48" tabindex="-1">Correction du programme de mise à jour 2.1.48 <a class="header-anchor" href="#correction-du-programme-de-mise-a-jour-2-1-48" aria-label="Permalink to &quot;Correction du programme de mise à jour 2.1.48&quot;">​</a></h3><p>Le transfert utilise désormais un handle de processus Windows stable au lieu de lire les modules de l’éditeur en cours de fermeture. Quatre tests supplémentaires couvrent x86/x64, les processus terminés, les identités incorrectes et les délais d’attente. Si l’ancien programme 2.1.37 échoue avant l’installation, extraire d’abord le ZIP 2.1.48 complet dans un nouveau dossier. Sauvegarder ses données et ne pas remplacer les bases et dictionnaires existants par ceux du paquet.</p><p>Le parcours complet de la version publiée 2.1.37 vers 2.1.48 a réussi sur une copie de test sauvegardée : téléchargement GitHub, installation et redémarrage automatique. Les 32 valeurs de configuration précédentes, 17 fichiers de données et de modèles contrôlés et 18 configurations utilisateur existantes ont été conservés. Une clé de test DPAPI synthétique est restée identique et déchiffrable ; l’état initial sans clé a ensuite été rétabli. Aucun appel OpenAI n’a été effectué. Le redémarrage a été confirmé par l’identifiant du processus, les versions, les empreintes et la configuration ; la capture de fenêtre Windows a échoué ensuite. Un nouveau test du dialogue GitHub en lecture seule a bien détecté 2.1.48.</p><h2 id="second-programme-info-trans" tabindex="-1">Second programme : Info_trans <a class="header-anchor" href="#second-programme-info-trans" aria-label="Permalink to &quot;Second programme : Info_trans&quot;">​</a></h2><p>Le paquet contient aussi <code>help/Info_trans.exe</code>. <strong>Aide de référence</strong> dans l’éditeur ouvre ce programme dans la langue choisie. La véritable <code>IET2.FDB</code> et son moteur natif Firebird 2.5.8 ont été récupérés dans l’archive de 2019. Aucune installation séparée d’un serveur Firebird n’est nécessaire.</p><p>La base contient 5 entrées de bâtiments, 2 de marchandises et 2 de mises à jour. Les tables des signaux, matériel roulant, objets de voie et paysage sont vides dans l’original. Sont aussi inclus : 236 entrées d’icônes, 369 termes techniques et 2 428 entrées corrigées dans le <strong>dictionnaire DE/EN/FR</strong>. L&#39;anglais est la référence ; les corrections allemandes confirmées et les traductions françaises sont intégrées. Les fragments ont été réunis et les termes mélangés séparés. Les variantes américaines et britanniques conservent leurs indications. Toutes les questions de vérification du dictionnaire sont résolues. Le fichier DE/EN original et la base source restent inchangés dans le paquet complet.</p><p><img src="'+a+'" alt="Info_trans 2.1.37 avec onglets Lime et base d&#39;origine chargée"></p><p><img src="'+o+'" alt="Dictionnaire trilingue Info_trans avec colonnes allemandes, anglaises et françaises lisibles"></p><p><code>Info_trans</code> est compilé pour x86, comme les DLL natives. Le fournisseur géré FirebirdSql.Data.FirebirdClient 7.5.0.0 a été vérifié avec la vraie base Firebird 2.5.8. Les tests lisent des copies séparées et comparent les sept tables avec l’interface DE/EN/FR. Le paquet contient la base source inchangée.</p><p>Les composants absents ou illisibles sont signalés ; l’import SQL est alors désactivé. Une sauvegarde locale précède tout import SQL manuel disponible. La mise à jour automatique du programme reste désactivée.</p><h2 id="donnees-et-confidentialite" tabindex="-1">Données et confidentialité <a class="header-anchor" href="#donnees-et-confidentialite" aria-label="Permalink to &quot;Données et confidentialité&quot;">​</a></h2><p>Les anciennes inscriptions et bases personnelles ne sont pas importées. Les paramètres sont séparés par utilisateur Windows. La configuration OpenAI et les sauvegardes sont conservées sous <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Windows DPAPI chiffre la clé API pour le compte Windows actuel. Les textes sélectionnés sont envoyés à OpenAI avec <code>store: false</code>. Internet et une facturation API distincte sont nécessaires ; un abonnement ChatGPT ne remplace pas cette facturation.</p><h2 id="mise-a-jour-et-verifications" tabindex="-1">Mise à jour et vérifications <a class="header-anchor" href="#mise-a-jour-et-verifications" aria-label="Permalink to &quot;Mise à jour et vérifications&quot;">​</a></h2><p><strong>Les mises à jour GitHub sont lancées manuellement et leur installation doit être confirmée.</strong> L’ancien serveur n’est pas utilisé. Google, LEO, Linguee et DeepL ne sont plus proposés.</p><p>41 contrôles locaux avec réponses API simulées et les compilations Debug/Release vérifient les erreurs, l’annulation, la restauration, l’export et les interfaces rendues DE/EN/FR. Aucun texte n’est envoyé à OpenAI pendant les tests. Un appel API réel et la qualité des traductions produites restent à vérifier avec son propre compte. Tous les schémas INI possibles ne sont pas pris en charge ; vérifier les données obtenues.</p><p>Le paquet local complet 2.1.37 a été contrôlé par l&#39;utilisateur, qui a confirmé son bon fonctionnement avant publication. Le ZIP contient les deux programmes, le moteur Firebird natif, la base originale et le dictionnaire corrigé. L&#39;intégrité du ZIP et son SHA-256 ont été vérifiés ; les sept tables de la base ont été comparées aux interfaces DE/EN/FR sur des copies séparées. Les captures montrent le nouveau design avec des données neutres, sans paramètres privés.</p>',86)])])}const h=t(d,[["render",l]]);export{g as __pageData,h as default};
